function validate(input) {
  const [arr, spec] = input;
  if (!Array.isArray(arr) || arr.length > 1000) return 'arr has at most 1000 elements.';
  if (!arr.every(n => Number.isInteger(n) && Math.abs(n) <= 1e9)) return 'Every element of arr is an integer from -10^9 to 10^9.';
  if (spec === 'identity') return null;
  const message = 'fn must be "identity", { "greaterThan": v }, { "plus": c }, { "mod": m }, { "indexIs": k } or { "returns": value }.';
  if (spec === null || typeof spec !== 'object' || Array.isArray(spec) || Object.keys(spec).length !== 1) return message;
  const [name] = Object.keys(spec), number = spec[name];
  if (name === 'returns') return null;
  if (!['greaterThan', 'plus', 'mod', 'indexIs'].includes(name)) return message;
  if (!Number.isInteger(number) || Math.abs(number) > 1e9) return `The number in ${name} must be an integer from -10^9 to 10^9.`;
  if (name === 'mod' && number === 0) return 'mod must not be 0.';
  return null;
}

