function adapt(input, solve, kit) {
  const [arr, spec] = input;
  const rule = spec === 'identity' ? (n) => n
    : 'greaterThan' in spec ? (n) => n > spec.greaterThan
    : 'plus' in spec ? (n) => n + spec.plus
    : 'mod' in spec ? (n) => n % spec.mod
    : 'indexIs' in spec ? (n, i) => i === spec.indexIs
    : () => spec.returns;
  const fn = (n, i) => {
    const value = rule(n, i);
    kit.trace(`fn(${n}, ${i}) returns ${JSON.stringify(value)}`);
    return value;
  };
  // The problem asks for a solution without the built-in filter, so it is switched off during the call.
  const builtIn = Array.prototype.filter;
  Array.prototype.filter = function () { throw new Error('Solve it without the built-in Array.prototype.filter.'); };
  let result;
  try {
    result = solve(arr, fn);
  } finally {
    Array.prototype.filter = builtIn;
  }
  if (!Array.isArray(result)) throw new Error('filter must return an array.');
  return result;
}

