function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const length = small ? Math.floor(rand() * 7) : 1000;
  const top = small ? 5 : 1000000000;
  const arr = Array.from({ length }, () => Math.floor(rand() * (2 * top + 1)) - top);
  const number = () => Math.floor(rand() * (2 * top + 1)) - top;
  const kind = pick(['identity', 'greaterThan', 'plus', 'mod', 'indexIs', 'returns']);
  if (kind === 'identity') return [arr, 'identity'];
  if (kind === 'greaterThan') return [arr, { greaterThan: number() }];
  if (kind === 'plus') return [arr, { plus: rand() < 0.5 && length > 0 ? -pick(arr) : number() }];
  if (kind === 'mod') return [arr, { mod: pick([1, 2, 3, -2, 5, small ? 4 : 1000]) }];
  if (kind === 'indexIs') return [arr, { indexIs: Math.floor(rand() * (length + 2)) - 1 }];
  return [arr, { returns: pick([true, false, 0, 1, -1, '', '0', 'false', null, [], {}, [0]]) }];
}
